var currentUser=null,currentPatient=null,selectedRole=null,prontuarioType=null,fabOpen=false,charts={};
function goTo(id){document.querySelectorAll('.screen').forEach(function(s){s.classList.remove('active')});document.getElementById(id).classList.add('active');closeAllMenus()}
function closeAllMenus(){document.querySelectorAll('.dropdown-menu').forEach(function(m){m.classList.remove('open')});closeFabAll()}
function closeFabAll(){fabOpen=false;['fabMenu','prontuarioSub'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none'});var f=document.getElementById('docFab');if(f)f.textContent='+'}
function toggleMenu(id){var m=document.getElementById(id);if(m)m.classList.toggle('open')}
function selectRole(r){selectedRole=r;document.querySelectorAll('.role-option').forEach(function(o){o.classList.remove('selected')});var el=document.getElementById('role-'+r);if(el)el.classList.add('selected');document.getElementById('roleSelector').style.display='none';document.getElementById('loginForm').classList.add('visible')}
function showRoleSelector(){document.getElementById('roleSelector').style.display='block';document.getElementById('loginForm').classList.remove('visible');selectedRole=null}
function toggleFamiliarExtra(){var v=document.getElementById('regRole').value;document.getElementById('regFamiliarExtra').style.display=v==='familiar'?'block':'none'}
function doLogin(){var email=(document.getElementById('loginEmail').value||'').trim().toLowerCase();var pass=document.getElementById('loginPassword').value;if(!email||!pass){showToast('Preencha email e senha','error');return}var user=DB.users.find(function(u){return u.email.toLowerCase()===email&&u.password===pass&&u.status==='ativo'});if(!user){showToast('Email ou senha incorretos','error');return}currentUser=user;showToast('Bem-vindo(a), '+user.name.split(' ')[0]+'!','success');loadScreen(user.role)}
function doRegister(){var name=(document.getElementById('regName').value||'').trim();var email=(document.getElementById('regEmail').value||'').trim();var pass=document.getElementById('regPassword').value;var role=document.getElementById('regRole').value;if(!name||!email||!pass||!role){showToast('Preencha todos os campos obrigatórios','error');return}if(DB.users.find(function(u){return u.email.toLowerCase()===email.toLowerCase()})){showToast('Email já cadastrado','error');return}var nu={id:'u'+Date.now(),name:name,email:email,password:pass,role:role,cargo:document.getElementById('regCargo').value,status:'pendente',createdAt:new Date().toLocaleDateString('pt-BR'),lastAccess:'-'};DB.users.push(nu);DB.pendingApprovals.push({id:'p'+Date.now(),name:name,email:email,role:role,date:new Date().toLocaleDateString('pt-BR')});showToast('Conta criada! Aguarde aprovação.','success');setTimeout(function(){goTo('screen-login')},1500)}
function loadScreen(role){switch(role){case 'admin':initAdmin();goTo('screen-admin');break;case 'doutor':initDoctor();goTo('screen-doctor');break;case 'recepcao':initRecepcao();goTo('screen-recepcao');break;case 'familiar':initFamiliar();goTo('screen-familiar');break}}
function logout(){currentUser=null;currentPatient=null;Object.values(charts).forEach(function(c){try{c.destroy()}catch(e){}});charts={};goTo('screen-landing');showToast('Você saiu do sistema','info')}
function initAdmin(){renderPending();renderContas();updateAdminStats()}
function showAdminTab(tab,el){document.querySelectorAll('.admin-tab').forEach(function(t){t.style.display='none'});document.getElementById('tab-'+tab).style.display='block';document.querySelectorAll('.admin-nav-item').forEach(function(i){i.classList.remove('active')});if(el)el.classList.add('active');if(tab==='contas')renderContas()}
function renderPending(){var list=document.getElementById('pendingList');var pending=DB.pendingApprovals;document.getElementById('pendingCount').textContent=pending.length+' contas aguardando aprovação';if(!pending.length){list.innerHTML='<p class="text-center text-muted" style="padding:24px;">Nenhuma aprovação pendente</p>';return}list.innerHTML=pending.map(function(p){return'<div style="display:flex;align-items:center;gap:14px;padding:16px 0;border-bottom:1px solid var(--border);"><div style="width:44px;height:44px;border-radius:50%;background:'+roleColor(p.role)+';display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;">'+roleIcon(p.role)+'</div><div style="flex:1;"><p class="font-bold">'+p.name+'</p><p class="text-sm text-muted">'+p.email+'</p><div style="display:flex;gap:6px;margin-top:4px;"><span class="badge '+roleBadgeClass(p.role)+'">'+roleLabel(p.role)+'</span><span class="text-xs text-muted">'+p.date+'</span></div></div><div style="display:flex;flex-direction:column;gap:6px;"><button class="btn btn-green" style="font-size:12px;padding:6px 14px;" onclick="approveUser(\''+p.id+'\')">✅ Aprovar</button><button class="btn btn-red" style="font-size:12px;padding:6px 14px;" onclick="rejectUser(\''+p.id+'\')">⛔ Rejeitar</button></div></div>'}).join('')}
function approveUser(id){var idx=DB.pendingApprovals.findIndex(function(p){return p.id===id});if(idx<0)return;var p=DB.pendingApprovals[idx];var u=DB.users.find(function(u){return u.email.toLowerCase()===p.email.toLowerCase()});if(u)u.status='ativo';DB.pendingApprovals.splice(idx,1);renderPending();renderContas();updateAdminStats();showToast('Conta de '+p.name+' aprovada!','success')}
function rejectUser(id){var idx=DB.pendingApprovals.findIndex(function(p){return p.id===id});if(idx<0)return;var p=DB.pendingApprovals[idx];DB.pendingApprovals.splice(idx,1);var uIdx=DB.users.findIndex(function(u){return u.email.toLowerCase()===p.email.toLowerCase()});if(uIdx>=0)DB.users.splice(uIdx,1);renderPending();renderContas();updateAdminStats();showToast('Conta rejeitada','error')}
function updateAdminStats(){var all=DB.users;document.getElementById('stat-total').textContent=all.length;document.getElementById('stat-ativas').textContent=all.filter(function(u){return u.status==='ativo'}).length;document.getElementById('stat-profs').textContent=all.filter(function(u){return u.role==='doutor'}).length;document.getElementById('stat-familiares').textContent=all.filter(function(u){return u.role==='familiar'}).length}
function renderContas(){var search=(document.getElementById('searchContas')&&document.getElementById('searchContas').value||'').toLowerCase();var tipo=document.getElementById('filterTipo')&&document.getElementById('filterTipo').value||'';var status=document.getElementById('filterStatus')&&document.getElementById('filterStatus').value||'';var users=DB.users.filter(function(u){if(search&&!u.name.toLowerCase().includes(search)&&!u.email.toLowerCase().includes(search)&&!(u.cargo||'').toLowerCase().includes(search))return false;if(tipo&&u.role!==tipo)return false;if(status&&u.status!==status)return false;return true});var cc=document.getElementById('contasCount');if(cc)cc.textContent='Mostrando '+users.length+' de '+DB.users.length+' contas';var cl=document.getElementById('contasList');if(!cl)return;cl.innerHTML=users.map(function(u){return'<div style="display:flex;align-items:flex-start;gap:14px;padding:16px;margin-bottom:10px;background:#fff;border-radius:var(--radius);border:1px solid var(--border);"><div style="width:44px;height:44px;border-radius:50%;background:'+roleColor(u.role)+';display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;">'+roleIcon(u.role)+'</div><div style="flex:1;"><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;"><span class="font-bold">'+u.name+'</span><span class="badge '+roleBadgeClass(u.role)+'">'+roleLabel(u.role)+'</span><span style="width:8px;height:8px;border-radius:50%;background:'+(u.status==='ativo'?'#4CAF50':'#ccc')+';display:inline-block;"></span></div><p class="text-sm text-muted">'+u.email+'</p><p class="text-xs text-muted">Cargo: '+(u.cargo||'-')+' | Criado: '+u.createdAt+' | Último acesso: '+u.lastAccess+'</p></div><div style="display:flex;flex-direction:column;gap:4px;min-width:90px;"><button class="btn btn-outline" style="font-size:11px;padding:5px 10px;" onclick="toggleUserStatus(\''+u.id+'\')">'+( u.status==='ativo'?'Desativar':'Ativar')+'</button><button class="btn btn-outline-green" style="font-size:11px;padding:5px 10px;" onclick="editUser(\''+u.id+'\')">✏️ Editar</button><button class="btn btn-outline-red" style="font-size:11px;padding:5px 10px;" onclick="deleteUser(\''+u.id+'\')">🗑️ Excluir</button></div></div>'}).join('')}
function toggleUserStatus(id){var u=DB.users.find(function(u){return u.id===id});if(!u)return;u.status=u.status==='ativo'?'inativo':'ativo';renderContas();updateAdminStats();showToast(u.name+' '+(u.status==='ativo'?'ativado':'desativado'),'info')}
function editUser(id){var u=DB.users.find(function(u){return u.id===id});if(!u)return;document.getElementById('ae-id').value=id;document.getElementById('ae-name').value=u.name;document.getElementById('ae-email').value=u.email;document.getElementById('ae-cargo').value=u.cargo||'';openModal('adminEditModal')}
function adminSaveEdit(){var id=document.getElementById('ae-id').value;var u=DB.users.find(function(u){return u.id===id});if(!u)return;u.name=document.getElementById('ae-name').value;u.email=document.getElementById('ae-email').value;u.cargo=document.getElementById('ae-cargo').value;closeModal('adminEditModal');renderContas();showToast('Conta atualizada!','success')}
function deleteUser(id){if(!confirm('Tem certeza que deseja excluir esta conta?'))return;var idx=DB.users.findIndex(function(u){return u.id===id});if(idx<0)return;DB.users.splice(idx,1);renderContas();updateAdminStats();showToast('Conta excluída','info')}
function adminCreateAccount(){var name=(document.getElementById('ac-name').value||'').trim();var email=(document.getElementById('ac-email').value||'').trim();var pass=document.getElementById('ac-password').value;var role=document.getElementById('ac-role').value;if(!name||!email||!pass){showToast('Preencha todos os campos','error');return}DB.users.push({id:'u'+Date.now(),name:name,email:email,password:pass,role:role,cargo:document.getElementById('ac-cargo').value,status:'ativo',createdAt:new Date().toLocaleDateString('pt-BR'),lastAccess:'-'});closeModal('adminCreateModal');renderContas();updateAdminStats();showToast('Conta criada com sucesso!','success')}
function initDoctor(){if(currentUser)document.getElementById('docGreeting').textContent='Olá, '+currentUser.name;document.getElementById('docDate').textContent='Data: '+new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});document.getElementById('docActivePat').textContent=DB.patients.length;renderDocAtivRecentes();renderEquipe();setTimeout(initDocCharts,200)}
function initDocCharts(){try{if(charts.docEvolucao)charts.docEvolucao.destroy();var ctx1=document.getElementById('docEvolucaoChart');if(ctx1)charts.docEvolucao=new Chart(ctx1,{type:'line',data:{labels:['Jan','Fev','Mar','Abr','Mai'],datasets:[{data:[65,67,69,72,78],borderColor:'#4CAF50',backgroundColor:'rgba(76,175,80,.1)',tension:.4,fill:true,pointBackgroundColor:'#4CAF50',pointRadius:5}]},options:{plugins:{legend:{display:false}},scales:{y:{min:0,max:100,grid:{color:'rgba(0,0,0,.06)'}},x:{grid:{display:false}}}}})}catch(e){}
try{if(charts.docDist)charts.docDist.destroy();var ctx2=document.getElementById('docDistChart');if(ctx2)charts.docDist=new Chart(ctx2,{type:'doughnut',data:{datasets:[{data:[8,10,6],backgroundColor:['#4CAF50','#64B5F6','#A5D6A7'],borderWidth:0}]},options:{plugins:{legend:{display:false}},cutout:'70%'}})}catch(e){}
try{if(charts.docAtiv)charts.docAtiv.destroy();var ctx3=document.getElementById('docAtivChart');if(ctx3)charts.docAtiv=new Chart(ctx3,{type:'bar',data:{labels:['Fono.','Terapia Ocu.','Psicologia','Fisio.'],datasets:[{data:[18,15,11,8],backgroundColor:'#4CAF50',borderRadius:6}]},options:{plugins:{legend:{display:false}},scales:{y:{grid:{color:'rgba(0,0,0,.06)'}},x:{grid:{display:false}}}}})}catch(e){}}
function renderDocAtivRecentes(){var items=[{nome:'Ana Clara Santos',tipo:'Sessão de Fonoaudiologia',hora:'09:00'},{nome:'Pedro Oliveira',tipo:'Terapia Ocupacional',hora:'10:30'},{nome:'Lucas Ferreira',tipo:'Avaliação Psicológica',hora:'14:00'}];document.getElementById('docAtivRecentes').innerHTML=items.map(function(i){return'<div style="display:flex;align-items:center;padding:12px;border-bottom:1px solid var(--border);cursor:pointer;"><div style="flex:1;"><p class="font-bold" style="font-size:14px;">'+i.nome+'</p><p class="text-xs text-muted">'+i.tipo+'</p></div><div style="display:flex;align-items:center;gap:6px;"><span style="font-size:13px;font-weight:600;">'+i.hora+'</span><span style="color:var(--text-light);">›</span></div></div>'}).join('')}
function renderEquipe(){var grid=document.getElementById('equipeGrid');if(!grid)return;grid.innerHTML=DB.equipe.map(function(e){return'<div style="text-align:center;padding:10px;border:1px solid var(--border);border-radius:var(--radius-sm);"><div style="width:40px;height:40px;border-radius:50%;background:#A5D6A7;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:14px;color:#2E7D32;margin:0 auto 6px;">'+e.ini+'</div><p style="font-size:11px;font-weight:700;color:var(--green-dark);">'+e.nome+'</p><p style="font-size:10px;color:var(--text-medium);">'+e.esp+'</p></div>'}).join('')}
function showDocTab(tab){['inicio','pacientes','relatorios','institucional'].forEach(function(t){var el=document.getElementById('doc-tab-'+t);if(el)el.style.display=t===tab?'block':'none';var nav=document.getElementById('docNav-'+t);if(nav)nav.classList.toggle('active',t===tab)});if(tab==='pacientes'){renderPatients();document.getElementById('patListView').style.display='block';document.getElementById('patDetailView').style.display='none';if(document.getElementById('salasView'))document.getElementById('salasView').style.display='none'}if(tab==='relatorios')setTimeout(initRelCharts,200);if(tab==='institucional')renderEquipe();if(tab==='inicio')setTimeout(initDocCharts,200);closeAllMenus()}
function initRelCharts(){try{if(charts.relDist)charts.relDist.destroy();var c1=document.getElementById('relDistChart');if(c1)charts.relDist=new Chart(c1,{type:'doughnut',data:{datasets:[{data:[18,15,12,8],backgroundColor:['#4CAF50','#64B5F6','#FF9800','#A5D6A7'],borderWidth:0}]},options:{plugins:{legend:{display:false}},cutout:'70%'}})}catch(e){}
try{if(charts.relEvol)charts.relEvol.destroy();var c2=document.getElementById('relEvolChart');if(c2)charts.relEvol=new Chart(c2,{type:'line',data:{labels:['Nov','Dez','Jan','Fev','Mar'],datasets:[{data:[65,68,70,72,78],borderColor:'#4CAF50',tension:.4,pointRadius:4,fill:false},{data:[46,50,52,50,52],borderColor:'#64B5F6',tension:.4,pointRadius:4,fill:false}]},options:{plugins:{legend:{display:false}},scales:{y:{min:0,max:100,grid:{color:'rgba(0,0,0,.06)'}},x:{grid:{display:false}}}}})}catch(e){}
try{if(charts.relIdade)charts.relIdade.destroy();var c3=document.getElementById('relIdadeChart');if(c3)charts.relIdade=new Chart(c3,{type:'bar',data:{labels:['0-3','4-6','7-9','10-12','13+'],datasets:[{data:[5,8,10,7,4],backgroundColor:'#4CAF50',borderRadius:6}]},options:{plugins:{legend:{display:false}},scales:{y:{grid:{color:'rgba(0,0,0,.06)'}},x:{grid:{display:false}}}}})}catch(e){}}
function renderPatients(){var list=document.getElementById('patientList');var search=(document.getElementById('patSearch')&&document.getElementById('patSearch').value||'').toLowerCase();var patients=DB.patients.filter(function(p){return!search||p.name.toLowerCase().includes(search)});if(document.getElementById('patCount'))document.getElementById('patCount').textContent=patients.length+' pacientes';if(document.getElementById('patCountLabel'))document.getElementById('patCountLabel').textContent=patients.length+' Pacientes';list.innerHTML=patients.map(function(p){return'<div class="patient-card" onclick="openPatient(\''+p.id+'\')"><div class="patient-avatar">'+p.name[0]+'</div><div class="patient-info"><div class="patient-name">'+p.name+'</div><div class="patient-meta">'+p.age+' anos &nbsp;'+p.diag.map(function(d){return'<span class="badge '+diagBadge(d)+'">'+d+'</span>'}).join(' ')+'</div><div class="progress-bar mt-4" style="width:160px;"><div class="progress-fill" style="width:'+p.progresso+'%;"></div></div><div class="text-xs" style="color:var(--green-dark);margin-top:2px;">'+p.progresso+'% &nbsp;|&nbsp; <span class="text-muted">Última sessão: '+(p.prontuarios[0]&&p.prontuarios[0].data||'-')+'</span></div></div><span style="color:var(--text-light);font-size:18px;">›</span></div>'}).join('')}
function diagBadge(d){if(d.includes('Leve'))return'badge-green';if(d.includes('Médio'))return'badge-blue';if(d.includes('Grave'))return'badge-red';if(d.includes('remissão'))return'badge-teal';return'badge-gray'}
function openPatient(id){currentPatient=DB.patients.find(function(p){return p.id===id});if(!currentPatient)return;document.getElementById('patListView').style.display='none';document.getElementById('patDetailView').style.display='block';document.getElementById('patDetailAvatar').textContent=currentPatient.name[0];document.getElementById('patDetailName').textContent=currentPatient.name;document.getElementById('patDetailAge').textContent=currentPatient.age+' anos · '+currentPatient.dob;document.getElementById('patDetailBadges').innerHTML=currentPatient.diag.map(function(d){return'<span class="badge" style="background:rgba(255,255,255,.25);color:#fff;border:1px solid rgba(255,255,255,.4);">'+d+'</span>'}).join('');document.getElementById('ph-progresso').textContent=currentPatient.progresso+'%';document.getElementById('ph-sessoes').textContent=currentPatient.sessoes;document.getElementById('ph-metas').textContent=currentPatient.metas;document.getElementById('ph-resp-nome').textContent=currentPatient.responsavel.nome;document.getElementById('ph-resp-tel').textContent=currentPatient.responsavel.tel;document.getElementById('ph-resp-email').textContent=currentPatient.responsavel.email;renderIndicadores();renderProntuario();renderRemedios();renderAtividades();renderDocs();showPatTab('home',document.querySelector('.patient-tab'));setTimeout(function(){initPatChart()},100)}
function initPatChart(){if(!currentPatient)return;try{if(charts.patEvol)charts.patEvol.destroy();var ctx=document.getElementById('patEvolChart');if(ctx)charts.patEvol=new Chart(ctx,{type:'line',data:{labels:['Nov','Dez','Jan','Fev','Mar','Mai'],datasets:[{data:currentPatient.evolucao,borderColor:'#4CAF50',backgroundColor:'rgba(76,175,80,.1)',tension:.4,fill:true,pointBackgroundColor:'#4CAF50',pointRadius:5}]},options:{plugins:{legend:{display:false}},scripts:{y:{min:0,max:100,grid:{color:'rgba(0,0,0,.06)'}},x:{grid:{display:false}}}}})}catch(e){}}
function backToPatList(){document.getElementById('patDetailView').style.display='none';document.getElementById('patListView').style.display='block';currentPatient=null}
function showPatTab(tab,el){['home','prontuario','remedios','atividades','docs'].forEach(function(t){var c=document.getElementById('patTab-'+t);if(c)c.classList.toggle('active',t===tab)});document.querySelectorAll('.patient-tab').forEach(function(t){t.classList.remove('active')});if(el)el.classList.add('active');closeFabAll()}
function renderIndicadores(){if(!currentPatient)return;var ind=currentPatient.indicadores;var icons={comunicacao:'💬',socializacao:'👥',comportamento:'🔄',autonomia:'⭐'};var labels={comunicacao:'Comunicação',socializacao:'Socialização',comportamento:'Comportamento',autonomia:'Autonomia'};document.getElementById('indicadoresContainer').innerHTML=Object.entries(ind).map(function(e){var k=e[0],v=e[1];return'<div class="indicator-row"><div class="indicator-label"><span>'+(icons[k]||'📊')+'</span>'+(labels[k]||k)+'</div><div style="flex:1;"><div class="progress-bar"><div class="progress-fill" style="width:'+v+'%;background:#333;"></div></div></div><div class="indicator-pct">'+v+'%</div></div>'}).join('');document.getElementById('editIndicadoresForm').innerHTML=Object.entries(ind).map(function(e){var k=e[0],v=e[1];return'<div class="form-group"><label>'+(labels[k]||k)+' (%)</label><input type="range" min="0" max="100" value="'+v+'" class="form-control" id="ind-'+k+'" oninput="document.getElementById(\'ind-val-'+k+'\').textContent=this.value" style="padding:4px;"><span id="ind-val-'+k+'">'+v+'</span>%</div>'}).join('')}
function openEditIndicadores(){openModal('editIndicadoresModal')}
function saveIndicadores(){if(!currentPatient)return;Object.keys(currentPatient.indicadores).forEach(function(k){var el=document.getElementById('ind-'+k);if(el)currentPatient.indicadores[k]=parseInt(el.value)});closeModal('editIndicadoresModal');renderIndicadores();showToast('Indicadores atualizados!','success')}
function renderProntuario(){if(!currentPatient)return;var typeColors={'Consulta':'#4CAF50','Exame':'#64B5F6','Terapia':'#FF9800'};var typeBadges={'Consulta':'badge-green','Exame':'badge-blue','Terapia':'badge-orange'};document.getElementById('prontuarioList').innerHTML=currentPatient.prontuarios.length?currentPatient.prontuarios.map(function(p){return'<div class="prontuario-entry '+p.tipo.toLowerCase()+'" style="border-left-color:'+(typeColors[p.tipo]||'#ccc')+'"><div class="flex justify-between items-center mb-4"><span class="badge '+(typeBadges[p.tipo]||'badge-gray')+'">'+p.tipo+'</span><span class="text-xs text-muted">'+p.data+'</span></div><p style="font-size:14px;font-weight:600;margin-bottom:4px;">'+p.titulo+'</p><p class="text-sm" style="color:var(--green-dark);">'+p.prof+'</p></div>'}).join(''):'<p class="text-center text-muted" style="padding:24px;">Nenhum registro no prontuário</p>'}
function renderRemedios(){if(!currentPatient)return;document.getElementById('remediosList').innerHTML=currentPatient.remedios.length?currentPatient.remedios.map(function(r){return'<div class="med-card"><div class="flex justify-between items-center"><div class="flex items-center gap-12"><div style="width:40px;height:40px;border-radius:50%;background:#E8F5E9;display:flex;align-items:center;justify-content:center;font-size:18px;">💊</div><div><p class="font-bold">'+r.nome+'</p><p class="text-sm text-muted">Dosagem: '+r.dosagem+'</p></div></div><div class="flex items-center gap-8"><span style="font-size:12px;color:var(--green);font-weight:700;">'+(r.ativo?'Ativado':'Desativado')+'</span><label class="toggle"><input type="checkbox" '+(r.ativo?'checked':'')+' onchange="toggleMed(\''+r.id+'\',this.checked)"><span class="toggle-slider"></span></label></div></div><div><p class="text-xs text-muted mt-8">Horários:</p><div class="med-times">'+r.horarios.map(function(h){return'<span class="med-time">🕐 '+h+'</span>'}).join('')+'</div></div><div><p class="text-xs text-muted mt-8">Dias da semana:</p><div class="day-chips">'+r.dias.map(function(d){return'<span class="day-chip">'+d+'</span>'}).join('')+'</div></div><div class="flex gap-8 mt-12"><button class="btn btn-outline-green" style="flex:1;font-size:12px;">✏️ Editar</button><button class="btn btn-outline-red" style="flex:1;font-size:12px;" onclick="deleteMed(\''+r.id+'\')">🗑️ Excluir</button></div></div>'}).join(''):'<p class="text-center text-muted" style="padding:24px;">Nenhum medicamento cadastrado</p>'}
function toggleMed(id,active){if(!currentPatient)return;var med=currentPatient.remedios.find(function(r){return r.id===id});if(med){med.ativo=active;showToast('Medicamento '+(active?'ativado':'desativado'),'info')}}
function deleteMed(id){if(!currentPatient)return;if(!confirm('Excluir este medicamento?'))return;currentPatient.remedios=currentPatient.remedios.filter(function(r){return r.id!==id});renderRemedios();showToast('Medicamento excluído','info')}
function renderAtividades(){if(!currentPatient)return;document.getElementById('atividadesList').innerHTML=currentPatient.atividades.length?currentPatient.atividades.map(function(a){return'<div class="activity-item"><div class="flex items-center gap-12 mb-8"><div style="width:36px;height:36px;border-radius:10px;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-size:16px;">⚡</div><div style="flex:1;"><div class="flex items-center gap-6"><span class="font-bold">'+a.nome+'</span><span class="badge '+(a.fromRecepcao?'badge-blue':'badge-green')+'">'+a.tipo+'</span></div><p class="text-xs text-muted">Frequência: '+a.freq+'</p><p class="text-xs text-muted">Próxima: '+a.proxima+'</p><p class="text-xs" style="color:var(--blue);">Profissional: '+a.prof+'</p></div></div>'+(a.fromRecepcao?'<div style="background:#E3F2FD;border-radius:var(--radius-sm);padding:8px;font-size:11px;color:var(--blue);margin-bottom:8px;">⚠️ Atividade criada pela recepção. Não pode ser editada pelo doutor.</div>':'')+'<div class="flex gap-8"><button class="btn btn-green" style="font-size:12px;padding:6px 14px;">✅ Concluir</button>'+(a.fromRecepcao?'<button class="btn btn-outline" style="font-size:12px;padding:6px 14px;" disabled>✏️ Somente visualização</button>':'<button class="btn btn-outline-green" style="font-size:12px;padding:6px 14px;">✏️ Editar</button>')+'</div></div>'}).join(''):'<p class="text-center text-muted" style="padding:24px;">Nenhuma atividade cadastrada</p>'}
function renderDocs(){if(!currentPatient)return;var mine=currentPatient.documentos.filter(function(d){return d.mine});var others=currentPatient.documentos.filter(function(d){return!d.mine});var typeColors={'Laudo':'badge-green','Relatório':'badge-blue','Documento':'badge-gray','Atestado':'badge-pink','Declaração':'badge-teal'};function renderDoc(d){return'<div class="doc-item"><div class="doc-icon">📄</div><div style="flex:1;"><p class="font-bold" style="font-size:13px;">'+d.nome+'</p><p class="text-xs text-muted">'+d.data+' · '+d.prof+'</p></div><span class="badge '+(typeColors[d.tipo]||'badge-gray')+'">'+d.tipo+'</span></div>'}
document.getElementById('docsList').innerHTML=(mine.length?'<p class="text-xs" style="color:var(--text-medium);font-weight:700;margin-bottom:8px;letter-spacing:.5px;">MEUS DOCUMENTOS</p>'+mine.map(renderDoc).join(''):'')+(others.length?'<p class="text-xs" style="color:var(--text-medium);font-weight:700;margin-bottom:8px;margin-top:12px;letter-spacing:.5px;">DOCUMENTOS DE OUTROS PROFISSIONAIS</p>'+others.map(renderDoc).join(''):'')+((!mine.length&&!others.length)?'<p class="text-center text-muted" style="padding:24px;">Nenhum documento</p>':'')}
function addPatient(){var nome=(document.getElementById('ap-nome').value||'').trim();var nasc=document.getElementById('ap-nasc').value;var diag=document.getElementById('ap-diag').value;if(!nome||!nasc){showToast('Preencha nome e data de nascimento','error');return}var dob=new Date(nasc);var age=new Date().getFullYear()-dob.getFullYear();DB.patients.push({id:'pat'+Date.now(),name:nome,dob:dob.toLocaleDateString('pt-BR'),age:age,diag:[diag],progresso:0,sessoes:0,metas:0,responsavel:{nome:document.getElementById('ap-resp-nome').value,tel:document.getElementById('ap-resp-tel').value,email:document.getElementById('ap-resp-email').value},indicadores:{comunicacao:0,socializacao:0,comportamento:0,autonomia:0},prontuarios:[],remedios:[],atividades:[],documentos:[],evolucao:[0,0,0,0,0,0]});closeModal('addPatientModal');renderPatients();showToast('Paciente '+nome+' adicionado!','success')}
function addMedicamento(){if(!currentPatient)return;var nome=(document.getElementById('med-nome').value||'').trim();var dos=(document.getElementById('med-dosagem').value||'').trim();var hor=(document.getElementById('med-horarios').value||'').trim();if(!nome||!dos||!hor){showToast('Preencha os campos obrigatórios','error');return}var dias=[];document.getElementById('diasCheckboxes').querySelectorAll('input:checked').forEach(function(cb){dias.push(cb.parentElement.textContent.trim())});currentPatient.remedios.push({id:'r'+Date.now(),nome:nome,dosagem:dos,horarios:hor.split(',').map(function(h){return h.trim()}),dias:dias,ativo:document.getElementById('med-ativo').checked,obs:document.getElementById('med-obs').value});closeModal('addMedModal');renderRemedios();showToast('Medicamento adicionado!','success')}
function addAtividade(){if(!currentPatient)return;var nome=(document.getElementById('atv-nome').value||'').trim();if(!nome){showToast('Informe o nome da atividade','error');return}currentPatient.atividades.push({id:'a'+Date.now(),nome:nome,tipo:document.getElementById('atv-tipo').value,freq:document.getElementById('atv-freq').value,proxima:document.getElementById('atv-data').value,prof:document.getElementById('atv-prof').value,fromRecepcao:false});closeModal('addAtividadeModal');renderAtividades();showToast('Atividade criada!','success')}
function toggleFabMenu(){fabOpen=!fabOpen;var fm=document.getElementById('fabMenu');var fab=document.getElementById('docFab');if(fm)fm.style.display=fabOpen?'flex':'none';if(fab)fab.textContent=fabOpen?'×':'+';if(!fabOpen){var ps=document.getElementById('prontuarioSub');if(ps)ps.style.display='none'}}
function showFabSub(id){var fm=document.getElementById('fabMenu');if(fm)fm.style.display='none';var sub=document.getElementById(id);if(sub)sub.style.display='flex'}
function openProntuario(type){prontuarioType=type;var titles={terapeutico:'🩷 Prontuário Terapêutico',clinico:'🩺 Prontuário Clínico',acompanhamento:'📊 Prontuário de Acompanhamento'};var subs={terapeutico:'Registro de sessão terapêutica',clinico:'Registro de consulta médica',acompanhamento:'Registro de evolução e acompanhamento'};document.getElementById('prontuarioModalTitle').textContent=titles[type]||'📋 Prontuário';document.getElementById('prontuarioModalSub').textContent=subs[type]||'';var saveBtn=document.getElementById('prontuarioSaveBtn');var colors={terapeutico:'#E91E63',clinico:'#1976D2',acompanhamento:'#7B1FA2'};if(saveBtn)saveBtn.style.background=colors[type]||'var(--green)';var content='';if(type==='terapeutico'){content='<div class="form-group"><label>Data <span class="req">*</span></label><input type="date" class="form-control" id="pron-data"></div><div class="form-group"><label>Profissional responsável <span class="req">*</span></label><input type="text" class="form-control" id="pron-prof" placeholder="Nome do profissional"></div><div class="form-group"><label>Tipo de terapia <span class="req">*</span></label><select class="form-control" id="pron-tipo"><option>Fonoaudiologia</option><option>Terapia Ocupacional</option><option>Psicologia</option><option>Fisioterapia</option></select></div><div class="form-group"><label>Objetivo da sessão <span class="req">*</span></label><textarea class="form-control" id="pron-objetivo" placeholder="Qual o objetivo desta sessão..."></textarea></div><div class="form-group"><label>Atividades realizadas <span class="req">*</span></label><textarea class="form-control" id="pron-atividades" placeholder="Descreva as atividades realizadas..."></textarea></div><div class="form-group"><label>Evolução do paciente <span class="req">*</span></label><textarea class="form-control" id="pron-evolucao" placeholder="Como o paciente evoluiu..."></textarea></div><div class="form-group"><label>Comportamento observado</label><textarea class="form-control" id="pron-comportamento" placeholder="Descreva o comportamento observado..."></textarea></div><div class="form-group"><label>Recomendações</label><textarea class="form-control" id="pron-rec" placeholder="Recomendações para próximas sessões..."></textarea></div>'}else if(type==='clinico'){content='<div class="form-group"><label>Data <span class="req">*</span></label><input type="date" class="form-control" id="pron-data"></div><div class="form-group"><label>Profissional <span class="req">*</span></label><input type="text" class="form-control" id="pron-prof" placeholder="Nome do profissional"></div><div class="form-group"><label>Queixa principal <span class="req">*</span></label><textarea class="form-control" id="pron-queixa" placeholder="Qual a queixa do paciente..."></textarea></div><div class="form-group"><label>Histórico resumido <span class="req">*</span></label><textarea class="form-control" id="pron-historico" placeholder="Histórico relevante..."></textarea></div><div class="form-group"><label>Avaliação clínica <span class="req">*</span></label><textarea class="form-control" id="pron-avaliacao" placeholder="Avaliação clínica..."></textarea></div><div class="form-group"><label>Diagnóstico / Hipótese <span class="req">*</span></label><textarea class="form-control" id="pron-diag" placeholder="Diagnóstico ou hipótese diagnóstica..."></textarea></div><div class="form-group"><label>Conduta <span class="req">*</span></label><textarea class="form-control" id="pron-conduta" placeholder="Conduta e orientações..."></textarea></div><div class="form-group"><label>Retorno</label><input type="text" class="form-control" id="pron-retorno" placeholder="Ex: Retorno em 30 dias"></div>'}else{content='<div class="form-group"><label>Data <span class="req">*</span></label><input type="date" class="form-control" id="pron-data"></div><div class="form-group"><label>Área <span class="req">*</span></label><select class="form-control" id="pron-area"><option>Comunicação</option><option>Socialização</option><option>Comportamento</option><option>Autonomia</option></select></div><div class="form-group"><label>Indicadores avaliados <span class="req">*</span></label><textarea class="form-control" id="pron-indicadores" placeholder="Quais indicadores foram avaliados..."></textarea></div><div class="form-group"><label>Evolução <span class="req">*</span></label><textarea class="form-control" id="pron-evolucao" placeholder="Como está a evolução do paciente..."></textarea></div><div class="form-group"><label>Pontos de atenção</label><textarea class="form-control" id="pron-atencao" placeholder="O que merece atenção especial..."></textarea></div><div class="form-group"><label>Plano de continuidade <span class="req">*</span></label><textarea class="form-control" id="pron-plano" placeholder="Planejamento e próximos passos..."></textarea></div>'}
document.getElementById('prontuarioModalContent').innerHTML=content;closeFabAll();openModal('prontuarioModal')}
function saveProntuario(){if(!currentPatient)return;var data=document.getElementById('pron-data')&&document.getElementById('pron-data').value;var prof=document.getElementById('pron-prof')&&document.getElementById('pron-prof').value;if(!data){showToast('Informe a data','error');return}var tipos={terapeutico:'Terapia',clinico:'Consulta',acompanhamento:'Consulta'};currentPatient.prontuarios.unshift({tipo:tipos[prontuarioType]||'Consulta',data:new Date(data).toLocaleDateString('pt-BR'),titulo:'Registro de '+(prontuarioType||'sessão')+' - '+new Date(data).toLocaleDateString('pt-BR'),prof:prof||currentUser&&currentUser.name||'Profissional'});closeModal('prontuarioModal');renderProntuario();showToast('Prontuário salvo!','success')}
function gerarAtestado(){var nome=(document.getElementById('at-nome').value||'').trim();if(!nome){showToast('Informe o nome do paciente','error');return}if(currentPatient)currentPatient.documentos.unshift({tipo:'Atestado',nome:'Atestado - '+nome,data:new Date().toLocaleDateString('pt-BR'),prof:document.getElementById('at-prof').value,mine:true});closeModal('atestadoModal');renderDocs();showToast('Atestado gerado!','success')}
function gerarDeclaracao(){var nome=(document.getElementById('dec-nome').value||'').trim();if(!nome){showToast('Informe o nome do paciente','error');return}if(currentPatient)currentPatient.documentos.unshift({tipo:'Declaração',nome:'Declaração - '+nome,data:new Date().toLocaleDateString('pt-BR'),prof:document.getElementById('dec-prof').value,mine:true});closeModal('declaracaoModal');renderDocs();showToast('Declaração gerada!','success')}
function updateAtestadoPreview(){var nome=document.getElementById('at-nome')&&document.getElementById('at-nome').value||'__________';var dias=document.getElementById('at-dias')&&document.getElementById('at-dias').value||'___';var data=document.getElementById('at-data')&&document.getElementById('at-data').value?new Date(document.getElementById('at-data').value).toLocaleDateString('pt-BR'):'____/____/____';var prof=document.getElementById('at-prof')&&document.getElementById('at-prof').value||'';document.getElementById('atestadoPreview').innerHTML='<p style="text-align:center;font-weight:700;margin-bottom:8px;">ATESTADO</p><p>Declaro que o(a) paciente <strong>'+nome+'</strong> esteve em atendimento nesta instituição e necessita de afastamento por <strong>'+dias+'</strong> dias.</p><p style="margin-top:8px;">Data: '+data+'</p>'+(prof?'<p style="margin-top:16px;border-top:1px solid #ccc;padding-top:8px;">'+prof+'</p>':'')}
function updateDeclaracaoPreview(){var nome=document.getElementById('dec-nome')&&document.getElementById('dec-nome').value||'__________';var data=document.getElementById('dec-data')&&document.getElementById('dec-data').value?new Date(document.getElementById('dec-data').value).toLocaleDateString('pt-BR'):'____/____/____';var hora=document.getElementById('dec-hora')&&document.getElementById('dec-hora').value||'________';document.getElementById('declaracaoPreview').innerHTML='<p style="text-align:center;font-weight:700;margin-bottom:8px;">DECLARAÇÃO</p><p>Declaro que o(a) paciente <strong>'+nome+'</strong> compareceu a atendimento nesta instituição.</p><p style="margin-top:8px;">Data: '+data+'<br>Horário: '+hora+'</p>'}
function initRecepcao(){if(currentUser)document.getElementById('recGreeting').textContent='Olá, '+currentUser.name.split(' ')[0]+'!';renderRecAgendamentos();renderAgendaList();renderSalas()}
function showRecTab(tab,el){['inicio','agenda','pacientes'].forEach(function(t){var e=document.getElementById('rec-tab-'+t);if(e)e.style.display=t===tab?'block':'none'});document.querySelectorAll('.rec-nav-item').forEach(function(i){i.classList.remove('active')});if(el)el.classList.add('active')}
function renderRecAgendamentos(){document.getElementById('recAgendamentos').innerHTML=DB.agendamentos.slice(0,3).map(function(a){return'<div class="agenda-item"><div style="width:44px;height:44px;border-radius:50%;background:var(--green-light);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;">🕐</div><div style="flex:1;"><div class="flex items-center gap-8 mb-4"><span style="font-weight:700;">'+a.hora+'</span><span class="badge badge-green">'+a.tipo+'</span></div><p style="font-size:13px;">Paciente: <strong>'+a.paciente+'</strong></p><p class="text-xs text-muted">Profissional: '+a.prof+'</p></div></div>'}).join('')}
function renderAgendaList(){document.getElementById('agendaList').innerHTML=DB.agendamentos.map(function(a){return'<div style="display:flex;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid var(--border);"><div style="width:40px;height:40px;border-radius:50%;background:var(--green-light);display:flex;align-items:center;justify-content:center;font-size:18px;">📅</div><div style="flex:1;"><div class="flex items-center gap-8 mb-2"><span class="font-bold">'+a.paciente+'</span><span class="badge badge-green">'+a.status+'</span></div><div class="flex gap-12 text-xs text-muted flex-wrap"><span>👤 '+a.prof+'</span><span>📅 '+a.data+'</span><span>🕐 '+a.hora+'</span><span>📋 '+a.tipo+'</span></div></div><button onclick="deleteAgend(\''+a.id+'\')" style="background:none;border:none;cursor:pointer;color:var(--red);font-size:16px;">🗑️</button></div>'}).join('')}
function renderSalas(){var grid=document.getElementById('salasList');if(!grid)return;grid.innerHTML=DB.salas.map(function(s){return'<div style="background:#fff;border-radius:var(--radius-lg);overflow:hidden;border:1px solid var(--border);"><div style="background:'+s.cor+';padding:16px;color:#fff;"><div class="flex justify-between items-start"><div style="width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;font-size:18px;">👥</div><button onclick="deleteSala(\''+s.id+'\')" style="background:rgba(255,255,255,.2);border:none;border-radius:6px;padding:4px 8px;cursor:pointer;color:#fff;font-size:12px;">🗑️</button></div><p style="font-weight:800;font-size:13px;margin-top:8px;">'+s.nome+'</p><p style="font-size:11px;opacity:.8;">'+s.desc+'</p></div><div style="padding:14px;"><p style="font-size:22px;font-weight:800;">'+s.pacientes+'</p><p class="text-xs text-muted mb-10">Pacientes cadastrados</p><button class="btn btn-green w-full" style="font-size:12px;">Ver pacientes ›</button></div></div>'}).join('')}
function addAgendamento(){var pac=(document.getElementById('ag-paciente').value||'').trim();var prof=(document.getElementById('ag-prof').value||'').trim();var data=document.getElementById('ag-data').value;var hora=document.getElementById('ag-hora').value;if(!pac||!prof||!data||!hora){showToast('Preencha todos os campos','error');return}DB.agendamentos.unshift({id:'ag'+Date.now(),paciente:pac,prof:prof,data:new Date(data).toLocaleDateString('pt-BR'),hora:hora,tipo:document.getElementById('ag-tipo').value,status:'Agendado'});closeModal('newAgendModal');renderRecAgendamentos();renderAgendaList();showToast('Agendamento criado!','success')}
function deleteAgend(id){if(!confirm('Cancelar este agendamento?'))return;DB.agendamentos=DB.agendamentos.filter(function(a){return a.id!==id});renderRecAgendamentos();renderAgendaList();showToast('Agendamento cancelado','info')}
function addSala(){var nome=(document.getElementById('sala-nome').value||'').trim();if(!nome){showToast('Informe o nome da sala','error');return}DB.salas.push({id:'s'+Date.now(),nome:nome,desc:document.getElementById('sala-desc').value,cor:document.getElementById('sala-cor').value,pacientes:0});closeModal('newSalaModal');renderSalas();showToast('Sala criada!','success')}
function deleteSala(id){if(!confirm('Excluir esta sala?'))return;DB.salas=DB.salas.filter(function(s){return s.id!==id});renderSalas();showToast('Sala excluída','info')}
function initFamiliar(){var pat=DB.patients[0];document.getElementById('famGreeting').textContent='Olá, '+pat.name.split(' ')[0]+'!';document.getElementById('famAge').textContent=pat.age+' anos';document.getElementById('famDate').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});document.getElementById('famMotivation').textContent='Continue seguindo a rotina para o melhor desenvolvimento de '+pat.name.split(' ')[0]+'.';renderFamRotina(pat);renderFamMeds(pat);renderFamAtivSemana(pat)}
function renderFamRotina(pat){var rotina=[{icon:'🍽️',nome:'Café da manhã',hora:'08:00',done:true},{icon:'💊',nome:'Medicamento - Risperidona 0,5mg',hora:'09:00',done:true},{icon:'🗣️',nome:'Sessão de Fonoaudiologia',hora:'10:00',done:false},{icon:'🍽️',nome:'Almoço',hora:'12:00',done:false},{icon:'🎨',nome:'Atividade sensorial',hora:'14:00',done:false},{icon:'💊',nome:'Medicamento - Risperidona 0,5mg',hora:'20:00',done:false},{icon:'💊',nome:'Medicamento - Melatonina 3mg',hora:'21:00',done:false}];document.getElementById('famRotina').innerHTML=rotina.map(function(r){return'<div style="display:flex;align-items:center;gap:12px;background:#fff;border-radius:var(--radius);padding:12px;margin-bottom:8px;border:1px solid var(--border);'+(r.done?'opacity:.6;':'')+'" onclick="this.style.opacity=.6"><div style="width:40px;height:40px;border-radius:50%;background:#F5F5F5;display:flex;align-items:center;justify-content:center;font-size:18px;">'+r.icon+'</div><div style="flex:1;"><p style="font-size:14px;'+(r.done?'text-decoration:line-through;color:var(--text-light);':'')+'">'+r.nome+'</p><p class="text-xs text-muted">'+r.hora+'</p></div>'+(r.done?'<div style="width:26px;height:26px;border-radius:50%;background:var(--green);display:flex;align-items:center;justify-content:center;color:#fff;font-size:14px;">✓</div>':'')+'</div>'}).join('')}
function renderFamMeds(pat){document.getElementById('famMeds').innerHTML=pat.remedios.filter(function(r){return r.ativo}).map(function(r){return'<div style="background:#fff;border-radius:var(--radius);padding:14px;margin-bottom:8px;border:1px solid var(--border);border-left:4px solid var(--green);"><div class="flex justify-between items-center"><div><p class="font-bold">'+r.nome+'</p><p class="text-sm text-muted">Dosagem: '+r.dosagem+'</p></div><div style="text-align:right;"><p class="text-xs text-muted">Horários:</p><div class="flex gap-4">'+r.horarios.map(function(h){return'<span class="badge badge-green" style="font-size:10px;">'+h+'</span>'}).join('')+'</div></div></div></div>'}).join('')}
function renderFamAtivSemana(pat){var hoje=new Date().getDay();var dias=[{dia:'Segunda',dow:1,ativs:['Fonoaudiologia 10h','Terapia Ocupacional 14h']},{dia:'Terça',dow:2,ativs:['Terapia Ocupacional 14h']},{dia:'Quarta',dow:3,ativs:['Fonoaudiologia 10h','Psicologia 15h']},{dia:'Quinta',dow:4,ativs:['Terapia Ocupacional 14h']},{dia:'Sexta',dow:5,ativs:['Fonoaudiologia 10h']}];document.getElementById('famAtivSemana').innerHTML=dias.map(function(d){var atual=d.dow===hoje;return'<div style="display:flex;align-items:center;gap:12px;background:'+(atual?'linear-gradient(135deg,#4CAF50,#64B5F6)':'#fff')+';border-radius:var(--radius);padding:12px;margin-bottom:8px;border:1px solid var(--border);"><div style="min-width:56px;text-align:center;"><span class="badge '+(atual?'':'badge-green')+'" style="'+(atual?'background:rgba(255,255,255,.25);color:#fff;':'')+'">'+d.dia+'</span></div><div>'+d.ativs.map(function(a){return'<p style="font-size:13px;'+(atual?'color:#fff;':'')+'">• '+a+'</p>'}).join('')+'</div></div>'}).join('')}
function roleIcon(r){return{admin:'🛡️',doutor:'🩺',recepcao:'👥',familiar:'🏠'}[r]||'👤'}
function roleColor(r){return{admin:'#F3E5F5',doutor:'#E3F2FD',recepcao:'#E8F5E9',familiar:'#FFF3E0'}[r]||'#F5F5F5'}
function roleLabel(r){return{admin:'Administrador',doutor:'Doutor / Profissional',recepcao:'Recepção',familiar:'Familiar / Paciente'}[r]||r}
function roleBadgeClass(r){return{admin:'badge-purple',doutor:'badge-blue',recepcao:'badge-green',familiar:'badge-orange'}[r]||'badge-gray'}
function openModal(id){var m=document.getElementById(id);if(m)m.classList.add('open')}
function closeModal(id){var m=document.getElementById(id);if(m)m.classList.remove('open')}
function showToast(msg,type){var tc=document.getElementById('toastContainer');var t=document.createElement('div');t.className='toast toast-'+(type||'info');t.innerHTML=(type==='success'?'✅':type==='error'?'❌':'ℹ️')+' '+msg;tc.appendChild(t);setTimeout(function(){t.remove()},3000)}
function copyPix(){navigator.clipboard&&navigator.clipboard.writeText('12.345.678/0001-90').catch(function(){});showToast('Chave PIX copiada!','success')}
document.querySelectorAll('.modal-overlay').forEach(function(overlay){overlay.addEventListener('click',function(e){if(e.target===overlay)overlay.classList.remove('open')})});
document.addEventListener('click',function(e){if(!e.target.closest('.dropdown-menu')&&!e.target.closest('.menu-btn'))document.querySelectorAll('.dropdown-menu').forEach(function(m){m.classList.remove('open')});if(!e.target.closest('.fab')&&!e.target.closest('.fab-menu')&&!e.target.closest('.fab-sub')&&fabOpen)closeFabAll()});
document.getElementById('docDate').textContent='Data: '+new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});
